115	
116	    const appOrigin = yield* Config.String("APP_ORIGIN").pipe(
117	      Config.withDefault(fallbackAppOrigin),
118	      Effect.orDie,
119	    );
120	
121	    const invitationKey = yield* Config.Redacted("INVITATION_TOKEN_KEY").pipe(
122	      Effect.flatMap((secret) => Effect.promise(() => importInvitationTokenKey(Redacted.value(secret)))),
123	      Effect.orDie,
124	    );
125	    const tokenOf = (ref: InvitationTokenRef) =>
126	      Effect.promise(() => deriveInvitationToken(invitationKey, ref));
127	
128	    const aiKey = yield* Config.Redacted("OPENROUTER_API_KEY").pipe(
129	      Config.withDefault(Redacted.make("")),
